edits.new_string:
// the Diagram (2D) and Scene (3D) views. With {@link ComposeDesignProps.splitLayout} `auto`,
// the scene column appears only when at least one piece has both plane and center.
// With `always`, the scene column is always allocated ({@link McpDesignViewer} uses this so
// the layout cannot collapse to a single full-width diagram when flattening fails).

/** How {@link ComposeDesign} chooses between one column (diagram only) vs split scene+diagram. */
export type ComposeDesignSplitLayout = "auto" | "always";

/**
 * Pure layout rule for {@link ComposeDesign} grid columns — unit-tested so MCP cannot regress to diagram-only full width.
 */
export function composeDesignGridTemplateColumns(splitLayout: ComposeDesignSplitLayout, hasPlanes: boolean, sceneRatio: number): string {
  const scenePercent = Math.max(0.1, Math.min(0.9, sceneRatio)) * 100;
  const diagramPercent = 100 - scenePercent;
  const showSplit = splitLayout === "always" || hasPlanes;
  return showSplit ? `${scenePercent}% ${diagramPercent}%` : "1fr";
}

/** Whether the scene (3D) column is mounted — must match {@link composeDesignGridTemplateColumns} split vs 1fr. */
export function composeDesignShowSceneColumn(splitLayout: ComposeDesignSplitLayout, hasPlanes: boolean): boolean {
  return splitLayout === "always" || hasPlanes;
}

